#include <iostream>
using namespace std;

struct Account {
	char owner[50];
	double balance;
};

void deposit(Account &acc, double amount) {
	acc.balance += amount;
}

int withdraw(Account &acc, double amount) {
	if (acc.balance >= amount) {
		acc.balance -= amount;
		return 1;
	}
	return 0;
}

void transfer(Account &from, Account &to, double amount) {
	if (withdraw(from, amount)) {
		deposit(to, amount);
	}
}

int main() {
	Account a1, a2;
	double amount;

	cin >> a1.owner >> a1.balance >> a2.owner >> a2.balance >> amount;

	transfer(a1, a2, amount);

	cout << a1.balance << endl;
	cout << a2.balance << endl;

	return 0;
}

