#include <iostream>
#include <string>

using namespace std;

int n, m;
int img[105][105];
int temp[105][105];

void crop(int x1, int y1, int x2, int y2)
{
    int new_n = x2 - x1 + 1;
    int new_m = y2 - y1 + 1;
    for (int i = 1; i <= new_n; i++) {
        for (int j = 1; j <= new_m; j++) {
            temp[i][j] = img[x1 + i - 1][y1 + j - 1];
        }
    }
    n = new_n;
    m = new_m;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            img[i][j] = temp[i][j];
        }
    }
}

void blur()
{
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            int sum = 0, count = 0;            
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int ni = i + di;
                    int nj = j + dj;
                    if (ni >= 1 && ni <= n && nj >= 1 && nj <= m) {
                        sum += img[ni][nj];
                        count++;
                    }
                }
            }
            temp[i][j] = sum / count;
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            img[i][j] = temp[i][j];
        }
    }
}

void rotate90()
{
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            temp[j][n - i + 1] = img[i][j];
        }
    }
    int old_n = n;
    n = m;
    m = old_n;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            img[i][j] = temp[i][j];
        }
    }
}

void print()
{
    cout << n << " " << m << "\n";
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            cout << img[i][j] << " ";
        }
        cout << "\n";
    }
}

// DO NOT MODIFY BELOW

int main()
{
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            cin >> img[i][j];
        }
    }
    string op;
    while (cin >> op && op != "EXIT") {
        if (op == "CROP") {
            int x1, y1, x2, y2;
            cin >> x1 >> y1 >> x2 >> y2;
            crop(x1, y1, x2, y2);
