#include <iostream>

using namespace std;

struct Node {
    int val;
    Node* next;
};

struct Stack {
    Node* top;

    void init();
    bool isEmpty();
    void push(int x);
    bool pop(int &out);
    bool peek(int &out);
    int size();
    void clear();
    void print();
    void reverseStack();
    bool moveToTop(int k);
    void rotateStack(int k);
};

// Do not modify above!!!

void Stack::init()
{
    top = NULL;
}

bool Stack::isEmpty()
{
    return top == NULL;
}

void Stack::push(int x)
{
    Node* newNode = new Node();
    newNode->val = x;
    newNode->next = top;
    top = newNode;
}

bool Stack::pop(int &out)
{
    if (isEmpty()) return false;
    Node* temp = top;
    out = temp->val;
    top = top->next;
    delete temp;
    return true;
}

bool Stack::peek(int &out)
{
    if (isEmpty()) return false;
    out = top->val;
    return true;
}

int Stack::size()
{
    int count = 0;
    Node* curr = top;
    while (curr) {
        count++;
        curr = curr->next;
    }
    return count;
}

void Stack::clear()
{
    while (top) {
        Node* temp = top;
        top = top->next;
        delete temp;
    }
}

void Stack::print()
{
    if (isEmpty()) {
        cout << "Empty" << endl;
        return;
    }
    Node* curr = top;
    while (curr) {
        cout << curr->val << " ";
        curr = curr->next;
    }
    cout << endl;
}

void Stack::reverseStack()
{
    if (isEmpty() || top->next == NULL) return;
    Node* prev = NULL;
    Node* current = top;
    Node* next = NULL;
    while (current) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    top = prev;
}

bool Stack::moveToTop(int k)
{
    if (k == 0) return true;
    if (isEmpty()) return false;
    Node* prev = NULL;
    Node* curr = top;
    int index = 0;
    while (curr && index < k) {
        prev = curr;
        curr = curr->next;
        index++;
    }
    if (curr == NULL) return false;
    prev->next = curr->next;
    curr->next = top;
    top = curr;
    return true;
}

void Stack::rotateStack(int k)
{
    if (isEmpty() || top->next == NULL) return;
    int n = size();
    k = k % n;
    if (k == 0) return;
    Node* tail = top;
    while (tail->next) {
        tail = tail->next;
    }
    tail->next = top;
    Node* newTail = top;
    for (int i = 0; i < n - k - 1; i++) {
        newTail = newTail->next;
    }
    top = newTail->next;
    newTail->next = NULL;
}

