#include <iostream>
#include <string>
using namespace std;

const int MAX_CANDIDATES = 10;
const int MAX_BALLOTS = 100;

struct Ballot {
	string code;
	string ranking[MAX_CANDIDATES];
	int size;
	bool valid;
};

string candidates[MAX_CANDIDATES];
bool eliminated[MAX_CANDIDATES];
int votes[MAX_CANDIDATES];
string usedCodes[MAX_BALLOTS];
int numUsedCodes = 0;

bool hasValidFormat(string code) {
	if (code.length() != 16) return false;
	if (code[4] != '-' || code[9] != '-' || code[14] != '-') return false;

	for (int i = 0; i < 16; i++) {
		if (i == 4 || i == 9 || i == 14) continue;
		if (code[i] < '0' || code[i] > '9') return false;
	}
	return true;
}

bool isValidChecksum(string code) {
	int sum = 0;
	int pos = 1;

	for (int i = 0; i < 14; i++) {
		if (code[i] == '-') continue;

		int digit = code[i] - '0';
		if (pos % 2 == 1) {
			sum += digit * 3;
		} else {
			sum += digit * 1;
		}
		pos++;
	}

	int checkDigit = (10 - (sum % 10)) % 10;
	int lastDigit = code[15] - '0';

	return checkDigit == lastDigit;
}

bool isDuplicate(string code) {
	for (int i = 0; i < numUsedCodes; i++) {
		if (usedCodes[i] == code) return true;
	}
	return false;
}

bool validateCode(string code) {
	if (!hasValidFormat(code)) return false;
	if (!isValidChecksum(code)) return false;
	if (isDuplicate(code)) return false;
	return true;
}

void markCodeAsUsed(string code) {
	usedCodes[numUsedCodes++] = code;
}

int findIndex(string name, int numCandidates) {
	for (int i = 0; i < numCandidates; ++i)
		if (candidates[i] == name) return i;
	return -1;
}

int readCandidates(int n) {
	for (int i = 0; i < n; ++i)
		cin >> candidates[i];
	return n;
}

int readBallots(Ballot ballots[], int numBallots, int numCandidates) {
	for (int i = 0; i < numBallots; ++i) {
		cin >> ballots[i].code;

		for (int j = 0; j < numCandidates; ++j)
			cin >> ballots[i].ranking[j];

		ballots[i].size = numCandidates;

		if (validateCode(ballots[i].code)) {
			ballots[i].valid = true;
			markCodeAsUsed(ballots[i].code);
		} else {
			ballots[i].valid = false;
		}
	}
	return numBallots;
}

void countVotes(Ballot ballots[], int numBallots, int numCandidates) {
	for (int i = 0; i < numCandidates; ++i) votes[i] = 0;

	for (int i = 0; i < numBallots; ++i) {
		if (!ballots[i].valid) continue;

		for (int j = 0; j < ballots[i].size; ++j) {
			int idx = findIndex(ballots[i].ranking[j], numCandidates);
			if (idx != -1 && !eliminated[idx]) {
				votes[idx]++;
				break;
			}
		}
	}
}

string runElection(Ballot ballots[], int numBallots, int numCandidates) {
	for (int i = 0; i < numCandidates; ++i)
		eliminated[i] = false;

	int validBallots = 0;
	for (int i = 0; i < numBallots; ++i) {
		if (ballots[i].valid) validBallots++;
	}

	int majority = validBallots / 2 + 1;

	while (true) {
		countVotes(ballots, numBallots, numCandidates);

		// Check for winner
		for (int i = 0; i < numCandidates; ++i)
			if (!eliminated[i] && votes[i] >= majority)
				return candidates[i];

		// Find lowest vote count
		int minVotes = -1;
		for (int i = 0; i < numCandidates; ++i)
			if (!eliminated[i] && (minVotes == -1 || votes[i] < minVotes))
				minVotes = votes[i];

		// Eliminate candidates with minVotes
		for (int i = 0; i < numCandidates; ++i)
			if (!eliminated[i] && votes[i] == minVotes)
				eliminated[i] = true;
	}
}

int main() {
	int numCandidates, numBallots;
	cin >> numCandidates >> numBallots;

	readCandidates(numCandidates);

	Ballot ballots[MAX_BALLOTS];
	readBallots(ballots, numBallots, numCandidates);

	cout << runElection(ballots, numBallots, numCandidates) << endl;
	return 0;
}

