    encryptedLetter = alphabet[(idx - pos + 26) % 26];
}

void encryptionBackThroughTheRotors(char& encryptedLetter, const string& rotor, int pos) {
    int idx = alphabet.find(encryptedLetter);
    idx = rotor.find(alphabet[(idx + pos) % 26]);
    encryptedLetter = alphabet[(idx - pos + 26) % 26];
}

string caesarShift(const string& str, int amount) {
    string output;
    for (unsigned char c : str) {
        if (c >= 'A' && c <= 'Z')
            c = ((c - 'A' + amount) % 26) + 'A';
        output += c;
    }
    return output;
}

