#include <iostream>
#include <string>
#include <vector>
#include <cmath>

using namespace std;

const int MAX_M = 100;
const int MAX_N = 1000;

struct Movie {
    string name;
    int features[MAX_M];
};

int target[MAX_M];
Movie movies[MAX_N];

inline long long square(long long x) {
    return x * x;
}

int main() {
    int n, m;

    cin >> n >> m;

    for (int i = 0; i < m; ++i) {
        cin >> target[i];
    }

    for (int i = 0; i < n; ++i) {
        cin >> movies[i].name;
        for (int j = 0; j < m; ++j) {
            cin >> movies[i].features[j];
        }
    }

    int best_index = 0;
    double min_dist = 1 << 24; // 2^24 = 16777216 > max possible distance: sqrt(MAX_M * 1000000^2) = sqrt(100 * 10^12) = 10^7

    for (int i = 0; i < n; ++i) {
        double sum_sq = 0;
        for (int j = 0; j < m; ++j) {
            sum_sq += square(target[j] - movies[i].features[j]);
        }

        double dist = sqrt(sum_sq);

        if (dist < min_dist) {
            min_dist = dist;
            best_index = i;
        }
    }

    cout << "Recommended Movie: " << movies[best_index].name << "\n";
    return 0;
}

