#include <cctype>
#include <iostream>
#include <limits>
#include <sstream>
#include <string>

using namespace std;

// ========================================================================
// ==== START OF SDK SECTION (correct implementation - DO NOT MODIFY ) ====
// ========================================================================

#define MAX_TYPES 15
#define MAX_MEMBERS 200
#define MAX_TOKENS 16
#define MAX_STRUCT_NAME 64

struct TypeInfo {
	int size;
	int alignment;
};

struct Member {
	string typeName;
	string name;
	bool isArray;
	int arraySize;
};

struct TypeEntry {
	string name;
	TypeInfo info;
};

struct ArrayParseResult {
	bool ok;
	string baseName;
	int count;
};

struct MemberParseResult {
	bool ok;
	Member member;
};

string trim(string s) {
	int start = 0;
	while (start < static_cast<int>(s.size()) &&
			isspace(static_cast<unsigned char>(s[start]))) {
		++start;
	}

	int end = static_cast<int>(s.size());
	while (end > start && isspace(static_cast<unsigned char>(s[end - 1]))) {
		--end;
	}

	return s.substr(start, end - start);
}

// Initializes the type table, with the correct sizes and alignments
int buildTypeTable(TypeEntry typeTable[MAX_TYPES]) {
	int count = 0;
	typeTable[count++] = {"char", {1, 1}};
	typeTable[count++] = {"signed char", {1, 1}};
	typeTable[count++] = {"unsigned char", {1, 1}};
	typeTable[count++] = {"short", {2, 2}};
	typeTable[count++] = {"unsigned short", {2, 2}};
	typeTable[count++] = {"int", {4, 4}};
	typeTable[count++] = {"unsigned int", {4, 4}};
	typeTable[count++] = {"long", {8, 8}};
	typeTable[count++] = {"unsigned long", {8, 8}};
	typeTable[count++] = {"long long", {8, 8}};
	typeTable[count++] = {"unsigned long long", {8, 8}};
	typeTable[count++] = {"float", {4, 4}};
	typeTable[count++] = {"double", {8, 8}};
	typeTable[count++] = {"long double", {16, 16}};
	typeTable[count++] = {"bool", {1, 1}};
	return count;
}

// Searches for type name in the type table, and returns the index it found, or -1 if not found
int findTypeIndex(TypeEntry typeTable[MAX_TYPES], int typeCount, string typeName) {
	for (int i = 0; i < typeCount; ++i) {
		if (typeTable[i].name == typeName) {
			return i;
		}
	}
	return -1;
}

void printOptimizedStruct(Member members[MAX_MEMBERS], int memberCount, int totalSize, char structName[MAX_STRUCT_NAME]) {
	cout << "struct " << structName << " {\n";
	for (int i = 0; i < memberCount; ++i) {
		Member m = members[i];
		cout << "    " << m.typeName << ' ' << m.name;
		if (m.isArray) {
			cout << '[' << m.arraySize << ']';
		}
		cout << ";\n";
	}
	cout << "};\n";

	cout << "\nDimensiune struct optimizat: " << totalSize << " octeti\n";
}

// ===========================================================================
// ==== END OF SDK SECTION (correct implementation - DO NOT MODIFY ABOVE) ====
// ===========================================================================


bool comesBefore(Member a, Member b,
		TypeEntry typeTable[MAX_TYPES], int typeCount) {
	int idxA = findTypeIndex(typeTable, typeCount, a.typeName);
	int idxB = findTypeIndex(typeTable, typeCount, b.typeName);

	if (idxA == -1 || idxB == -1) {
		return a.name < b.name;
	}

	TypeInfo infoA = typeTable[idxA].info;
	TypeInfo infoB = typeTable[idxB].info;

	if (infoA.alignment != infoB.alignment) {
		return infoA.alignment > infoB.alignment;
	}

	int countA = a.isArray ? a.arraySize : 1;
	int countB = b.isArray ? b.arraySize : 1;
	int sizeA = infoA.size * countA;
	int sizeB = infoB.size * countB;
	if (sizeA != sizeB) {
		return sizeA > sizeB;
	}

	return a.name < b.name;
}

void optimizeAndPrintStruct(Member members[MAX_MEMBERS], int memberCount,
		TypeEntry typeTable[MAX_TYPES], int typeCount,
		char structName[MAX_STRUCT_NAME]) {
	for (int i = 0; i < memberCount - 1; ++i) {
		int bestIndex = i;
		for (int j = i + 1; j < memberCount; ++j) {
			if (comesBefore(members[j], members[bestIndex], typeTable, typeCount)) {
				bestIndex = j;
			}
		}

		if (bestIndex != i) {
			Member temp = members[i];
			members[i] = members[bestIndex];
			members[bestIndex] = temp;
		}
	}

	int offset = 0;
	int maxAlignment = 1;
	for (int i = 0; i < memberCount; ++i) {
		Member m = members[i];
		int idx = findTypeIndex(typeTable, typeCount, m.typeName);
		if (idx == -1) {
			continue;
		}
		TypeInfo info = typeTable[idx].info;
		int count = m.isArray ? m.arraySize : 1;
		int padding = (info.alignment - (offset % info.alignment)) % info.alignment;
		int memberOffset = offset + padding;
		int memberSize = info.size * count;

		offset = memberOffset + memberSize;
		if (info.alignment > maxAlignment) {
			maxAlignment = info.alignment;
		}
	}

	int finalPadding = (maxAlignment - (offset % maxAlignment)) % maxAlignment;
	int totalSize = offset + finalPadding;

	printOptimizedStruct(members, memberCount, totalSize, structName);
}

// ====================================================================================
// ==== START OF READ_INPUT SECTION (correct implementation - DO NOT MODIFY BELOW) ====
// ====================================================================================

ArrayParseResult parseArraySuffix(string nameToken) {
	ArrayParseResult result;
	result.ok = true;
	result.baseName = nameToken;
	result.count = 1;

	int open = static_cast<int>(nameToken.find('['));
	if (open == -1) {
		return result;
	}

	int close = static_cast<int>(nameToken.find(']', open + 1));
	if (close == -1 || close != static_cast<int>(nameToken.size()) - 1) {
		result.ok = false;
		return result;
	}

	result.baseName = nameToken.substr(0, open);
	string inside = nameToken.substr(open + 1, close - open - 1);
	inside = trim(inside);
	if (inside.empty()) {
		result.ok = false;
		return result;
	}

	for (char ch : inside) {
		if (!isdigit(static_cast<unsigned char>(ch))) {
			result.ok = false;
			return result;
		}
	}

	int value = 0;
	for (char ch : inside) {
		int digit = static_cast<int>(ch - '0');
		if (value > (numeric_limits<int>::max() - digit) / 10) {
			result.ok = false;
			return result;
		}
		value = value * 10 + digit;
	}

	result.count = value;
	if (result.count <= 0) {
		result.ok = false;
	}
	return result;
}

MemberParseResult parseMemberLine(string rawLine) {
	MemberParseResult result;
	result.ok = false;

	string line = trim(rawLine);
	if (line.empty()) {
		return result;
	}

	if (line.back() != ';') {
		return result;
	}
	line.pop_back();
	line = trim(line);
	if (line.empty()) {
		return result;
	}

	stringstream ss(line);
	string tokens[MAX_TOKENS];
	int tokenCount = 0;
	string token;
	while (ss >> token) {
		if (tokenCount >= MAX_TOKENS) {
			return result;
		}
		tokens[tokenCount++] = token;
	}

	if (tokenCount < 2) {
		return result;
	}

	string nameToken = tokens[tokenCount - 1];
	string typeName;
	for (int i = 0; i < tokenCount - 1; ++i) {
		if (i > 0) {
			typeName += ' ';
		}
		typeName += tokens[i];
	}

	ArrayParseResult arrayInfo = parseArraySuffix(nameToken);
	if (!arrayInfo.ok) {
		return result;
	}

	result.member.typeName = typeName;
	result.member.name = arrayInfo.baseName;
	result.member.isArray = (arrayInfo.count > 1);
	result.member.arraySize = arrayInfo.count;
	result.ok = !result.member.name.empty();
	return result;
}

void copyToCharArray(string source, char destination[MAX_STRUCT_NAME]) {
	int i = 0;
	while (i < MAX_STRUCT_NAME - 1 && i < static_cast<int>(source.size())) {
		destination[i] = source[i];
		++i;
	}
	destination[i] = '\0';
}

void drainUntilStructEnd() {
	string line;
	while (getline(cin, line)) {
		if (trim(line) == "};") {
			break;
		}
	}
}

int main() {
	TypeEntry typeTable[MAX_TYPES];
	int typeCount = buildTypeTable(typeTable);
	Member members[MAX_MEMBERS];
	int memberCount = 0;
	char structName[MAX_STRUCT_NAME] = "Optimized";

	string line;
	while (getline(cin, line)) {
		string t = trim(line);
		if (t == "};") {
			break;
		}

		if (t.empty()) {
			continue;
		}

		if (t.find('{') != string::npos) {
			stringstream ss(t);
			string word;
			ss >> word;
			if (word == "struct") {
				string name;
				ss >> name;
				if (!name.empty()) {
					copyToCharArray(name, structName);
				}
			}
			continue;
		}

		MemberParseResult parsed = parseMemberLine(t);
		if (!parsed.ok) {
			drainUntilStructEnd();
			cout << "Linie invalida: " << t << "\n";
			return 1;
		}
		Member member = parsed.member;

		if (findTypeIndex(typeTable, typeCount, member.typeName) == -1) {
			drainUntilStructEnd();
			cout << "Tip nesuportat: " << member.typeName << "\n";
			return 1;
		}

		if (memberCount >= MAX_MEMBERS) {
			drainUntilStructEnd();
			cout << "Prea multi membri in struct.\n";
			return 1;
		}
		members[memberCount++] = member;
	}

	if (memberCount == 0) {
		cout << "Nu exista membri in struct.\n";
		return 0;
	}

	optimizeAndPrintStruct(members, memberCount, typeTable, typeCount, structName);

	return 0;
}

