#include <iostream>
#include <cstring>

using namespace std;

struct User {
    char name[25];
    int balance;
    bool suspicious;
};

User users[55];
int user_count = 0;

int find_user(char* name) {
    for (int i = 0; i < user_count; i++) {
        if (strcmp(users[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    int n;
    cin >> n;

    for (int i = 0; i < n; i++) {
        char command[20];
        cin >> command;
        if (strcmp(command, "REGISTER") == 0) {
            char user[25];
            cin >> user;
            if (find_user(user) == -1) {
                strcpy(users[user_count].name, user);
                users[user_count].balance = 0;
                users[user_count].suspicious = false;
                user_count++;
            }
        } else if (strcmp(command, "DEPOSIT") == 0) {
            char user[25];
            int amount;
            cin >> user >> amount;
            int idx = find_user(user);
            if (idx != -1 && !users[idx].suspicious) {
                users[idx].balance += amount;
            }
        } else if (strcmp(command, "TRANSFER") == 0) {
            char sender[25], receiver[25];
            int amount;
            cin >> sender >> receiver >> amount;
            int s_idx = find_user(sender);
            int r_idx = find_user(receiver);
            if (s_idx != -1 && r_idx != -1) {
                if (!users[s_idx].suspicious && !users[r_idx].suspicious) {
                    if (users[s_idx].balance >= amount) {
                        users[s_idx].balance -= amount;
                        users[r_idx].balance += amount;
                    } else {
                        users[s_idx].suspicious = true;
                    }
                }
            }
        } else if (strcmp(command, "STATUS") == 0) {
            char user[25];
            cin >> user;
            int idx = find_user(user);
            if (idx != -1) {
                if (users[idx].suspicious) {
                    cout << user << " SUSPICIOUS\n";
                } else {
                    cout << user << " " << users[idx].balance << "\n";
                }
            }
        }
    }

    for (int i = 0; i < user_count - 1; i++) {
        for (int j = i + 1; j < user_count; j++) {
            if (strcmp(users[i].name, users[j].name) > 0) {
                User temp = users[i];
                users[i] = users[j];
                users[j] = temp;
            }
        }
    }

    cout << "FINAL_REPORT\n";
    for (int i = 0; i < user_count; i++) {
        if (users[i].suspicious) {
            cout << users[i].name << " FRAUD_SUSPICION\n";
        } else {
            cout << users[i].name << " " << users[i].balance << "\n";
        }
    }

    return 0;
}

