#include <iostream>
#include <string>

using namespace std;

#define MAX_NODES 100

struct Node {
  char data;
  int freq;
  Node *left;
  Node *right;
};

Node *buildHuffmanTree(const char text[]) {
  // -----------------------------------------------------------------------------
  // DO NOT MODIFY BELOW
  // -----------------------------------------------------------------------------

  // System initialization: Frequency counting and leaf generation

  Node *nodes[MAX_NODES];
  int num_nodes = 0;

  // Compute character frequencies directly from the null-terminated array
  int freqs[256] = {0};
  for (int i = 0; text[i] != '\0'; i++) {
    freqs[(unsigned char)text[i]]++;
  }

  // Populate active array of valid Huffman leaf nodes
  for (int i = 0; i < 256; i++) {
    if (freqs[i] > 0) {
      nodes[num_nodes] = new Node;
      nodes[num_nodes]->data = (char)i;
      nodes[num_nodes]->freq = freqs[i];
      nodes[num_nodes]->left = nullptr;
      nodes[num_nodes]->right = nullptr;
      num_nodes++;
    }
  }

  if (num_nodes == 0)
    return nullptr;

  // Used array replaces the need for a 'parent' pointer in Node struct
  bool used[MAX_NODES] = {false};
  Node *root = nullptr;

  // -----------------------------------------------------------------------------
  // DO NOT MODIFY ABOVE
  // -----------------------------------------------------------------------------

  while (true) {
    int a = -1;
    int b = -1;

    // Find the two nodes with minimum frequencies that are not used yet
    for (int i = 0; i < num_nodes; i++) {
      if (!used[i]) {
        if (a == -1 || nodes[i]->freq < nodes[a]->freq) {
          b = a;
          a = i;
        } else if (b == -1 || nodes[i]->freq < nodes[b]->freq) {
          b = i;
        }
      }
    }

    if (b == -1) {
      root = nodes[a];
      break;
    }

    used[a] = true;
    used[b] = true;

    // Create a new internal node
    Node *new_node = new Node();
    new_node->data = '*';
    new_node->freq = nodes[a]->freq + nodes[b]->freq;
    new_node->left = nodes[a];
    new_node->right = nodes[b];

    nodes[num_nodes++] = new_node;
  }

  return root;
}

bool printCode(Node *root, char target, char code[16], int len) {
  if (root == nullptr)
    return false;

  // If it reached a leaf node
  if (root->left == nullptr && root->right == nullptr) {
    if (root->data == target) {
      // Special case: single-character tree (root is also a leaf)
      if (len == 0) {
        cout << '0';
        return true;
      }
      // Print the code
      for (int i = 0; i < len; i++)
        cout << code[i];
      return true;
    }
    return false;
  }

  code[len] = '0';
  if (printCode(root->left, target, code, len + 1))
    return true;

  code[len] = '1';
  if (printCode(root->right, target, code, len + 1))
    return true;

  return false;
}

// -----------------------------------------------------------------------------
// DO NOT MODIFY BELOW
// -----------------------------------------------------------------------------

void deleteTree(Node *node) {
  if (node == nullptr)
    return;
  deleteTree(node->left);
  deleteTree(node->right);
  delete node;
}

int main() {
  string text;
  if (!getline(cin, text))
    return 0;

  Node *root = buildHuffmanTree(text.c_str());
  if (!root)
    return 0;

  int num_queries;
  if (cin >> num_queries) {
    for (int i = 0; i < num_queries; i++) {
      char q;
      cin >> q;
      cout << q << " : ";
      char code[16];
      bool found = printCode(root, q, code, 0);
      if (!found)
        cout << "Not Found";
      cout << "\n";
    }
  }

  deleteTree(root);
  return 0;
}

