matrix_t matrix_t::operator+(const matrix_t &other) // DO NOT MODIFY
{
	// Check if the matrices have the same dimensions
	if (this->rows != other.rows || this->cols != other.cols)
	{
		return matrix_t::identity(1);
	}

	// Create new matrix with the dimensions
	matrix_t result(this->rows, this->cols);

	// Iterate the two matrices and add the values
	for (int i = 0; i < this->rows; i++)
	{
		for (int j = 0; j < this->cols; j++)
		{
			result.data[i][j] = this->data[i][j] + other.data[i][j];
		}
	}

	return result;
}

matrix_t matrix_t::operator-(const matrix_t &other)
{
	// Check if the matrices have the same dimensions
	if (this->rows != other.rows || this->cols != other.cols)
	{
		return matrix_t::identity(1);
	}

	// Create new matrix with the dimensions
	matrix_t result(this->rows, this->cols);

	// Iterate the two matrices and subtract
	for (int i = 0; i < this->rows; i++)
	{
		for (int j = 0; j < this->cols; j++)
		{
			result.data[i][j] = this->data[i][j] - other.data[i][j];
		}
	}

	return result;
}

matrix_t matrix_t::operator*(int scalar)
{
