using namespace std;

int main()
{
    int n, m, i, j, k;
    int a[101], b[101];
    int c[202];

    cin >> n >> m;
    for (i = 1; i <= n; i++)
    {
        cin >> a[i];
    }
    for (i = 1; i <= m; i++)
    {
        cin >> b[i];
    }

    i = 1;
    j = 1;
    k = 0;

    // parcurg ambele siruri simultan si iau elementul mai mic, cat timp mai am elemente in ambele siruri
    while (i <= n && j <= m)
    {
        if (a[i] < b[j])
        {
            k++;
            c[k] = a[i];
            i++;
        }
        else
        {
            k++;
            c[k] = b[j];
            j++;
        }
    }
    // daca am ajuns aici, inseamna ca ori unul dintre siruri s-a terminat, ori ambele s-au terminat

    while (i <= n) // daca mai am elemente in primul sir, le adaug pe toate
    {
        ++k;
        c[k] = a[i];
        i++;
    }
    while (j <= m) // daca mai am elemente in al doilea sir, le adaug pe toate
    {
        ++k;
        c[k] = b[j];
        j++;
    }

    for (i = 1; i <= k; i++)
    {
        cout << c[i] << " ";
    }
    return 0;
}

