#include <iostream>

using namespace std;

struct error {
	int line;
	int column;
};

// calculeaza suma elementelor de pe o linie
int sum_line(int a[101][101], int m, int line)
{
	int s = 0;
	for (int j = 1; j <= m; j++) {
		s += a[line][j];
	}
	return s;
}

// calculeaza suma elementelor de pe o coloana
int sum_column(int a[101][101], int n, int column)
{
	int s = 0;
	for (int i = 1; i <= n; i++) {
		s += a[i][column];
	}
	return s;
}

// corecteaza o eroare in functie ori de suma pe linie ori de suma pe coloana
int correct_value(int a[101][101], int n, int m, error errors[101], int i, int j, bool sameLine)
{
    if (sameLine) {
        return a[i][j] - (sum_column(a, n, j) - a[0][j]);
    } else {
        return a[i][j] - (sum_line(a, m, i) - a[i][0]);
    }
}

// corecteaza erorile
void correct_errors(int a[101][101], int n, int m, error errors[101],
						  int numberOfErrors, bool sameLine)
{
	for (int i = 1; i <= numberOfErrors; i++) {
		a[errors[i].line][errors[i].column] = correct_value(a, n, m, errors, errors[i].line, errors[i].column, sameLine);
	}
}

// deoarece toate erorile se afla pe aceeasi linie sau pe aceeasi coloana
// trebuie sa completam erorile coloana sau linia fiecarui element din errors
void complete_errors(error errors[101], int columnsChanged, int linesChanged)
{
	if (columnsChanged == 1) {
		for (int i = columnsChanged + 1; i <= linesChanged; i++) {
			errors[i].column = errors[1].column;
		}
	} else { // linesChanged == 1
		for (int i = linesChanged + 1; i <= columnsChanged; i++) {
			errors[i].line = errors[1].line;
		}
	}
}

// verifica daca exista eroare si daca da, incearca sa o corecteze
int check_error(int a[101][101], int n, int m)
{
	error errors[101];
	int linesChanged = 0;

	for (int i = 1; i <= n; i++) {
		int s = sum_line(a, m, i);
		if (a[i][0] != s) {
			errors[++linesChanged].line = i;
		}
	}

	int columnsChanged = 0;
	for (int j = 1; j <= m; j++) {
		int s = sum_column(a, n, j);
		if (a[0][j] != s) {
			errors[++columnsChanged].column = j;
		}
	}

	if (linesChanged) {
		if (linesChanged >= 2 && columnsChanged >= 2) {
			return 2;
		}
		// daca am ajuns aici, inseamna ca toate erorile se pot gasi pe aceeasi
		// coloana, sau pe aceeasi linie
        // mai este nevoie sa completam erorile
		complete_errors(errors, columnsChanged, linesChanged);
        bool sameLine = true; // presupunem ca erorile sunt doar pe o singura linie
		if (linesChanged > 1) {
			sameLine = false; // erorile se afla pe o singura coloana
		}
        correct_errors(a, n, m, errors, max(columnsChanged, linesChanged), sameLine);
		return 1;
	}
	return 0;
}

// decide care este elementul cel mai comun din cele 3
int most_common_element(int a, int b, int c)
{
	if (a == b) {
		return a;
	} else if (a == c) {
		return a;
	} else { // b == c
		return b;
	}
}

// creeaza un array care are pe fiecare pozitie cel mai comun element de
// pe acea pozitie din cele 3 array-uri
void create_majority_array(int array[101], int arrayA[101], int arrayB[101],
						   int arrayC[101], int size)
{
	for (int i = 1; i <= size; i++) {
		array[i] = most_common_element(arrayA[i], arrayB[i], arrayC[i]);
	}
}

// ataseaza checksum-urile la matrice
void attach_checksum(int a[101][101], int n, int m, int linesum[101],
					 int columnsum[101])
{
	for (int i = 1; i <= n; i++) {
		a[i][0] = linesum[i];
	}

	for (int j = 1; j <= m; j++) {
		a[0][j] = columnsum[j];
	}
}

// afiseaza mesajul
void print_message(int a[101][101], int n, int m)
{
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			cout << a[i][j] << " ";
		}
		cout << '\n';
	}
}

// citeste mesajul
void read_message(int a[101][101], int &n, int &m)
{
	cin >> n >> m;
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			cin >> a[i][j];
		}
	}
}

// citeste un singur checksum
void read_checksum(int a[101], int n)
{
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
	}
}

// citeste checksum-urile si le atasam la matrice
void read_and_attach_checksum(int a[101][101], int n, int m)
{
	int linesumA[101], linesumB[101], linesumC[101], linesum[101];
	read_checksum(linesumA, n);
	read_checksum(linesumB, n);
	read_checksum(linesumC, n);
	create_majority_array(linesum, linesumA, linesumB, linesumC, n);

	int columnsumA[101], columnsumB[101], columnsumC[101], columnsum[101];
	read_checksum(columnsumA, m);
	read_checksum(columnsumB, m);
	read_checksum(columnsumC, m);
	create_majority_array(columnsum, columnsumA, columnsumB, columnsumC, m);

	attach_checksum(a, n, m, linesum, columnsum);
}

int main()
{
	int n, m, a[101][101];
	read_message(a, n, m);
	read_and_attach_checksum(a, n, m);

	int error = check_error(a, n, m);
	if (error == 0 || error == 1) {
		if (error == 0) {
			cout << "Mesajul nu a fost compromis\n";
		} else {
			cout << "Mesajul a fost compromis si a fost corectat\n";
		}
		print_message(a, n, m);
	} else { // error == 2
		cout << "Mesajul a fost compromis si nu a putut fi corectat\n";
	}
	return 0;
}

