bool tryPosition(const Position& p, int cnt, queue<Position>& q)
{
	if (!inBounds(p) || block[p.lin][p.col])
		return false;

	if (len[p.lin][p.col] == 0 || cnt + 1 < len[p.lin][p.col]) {
		len[p.lin][p.col] = cnt + 1;
		q.push(p);
	}

