#include <functional>
#include <algorithm>

using error_type_t = std::string;
using token_stream_t = std::vector<std::string>;

class Literal;
class Addition;
class Multiplication;

class ASTVisitor {
public:
    ~ASTVisitor() {};

    virtual int visit(Literal&) = 0;
    virtual int visit(Addition&) = 0;
    virtual int visit(Multiplication&) = 0;
};

class Expression {
public:
    virtual ~Expression() = default;

    virtual int accept(ASTVisitor&) = 0;

private:
    friend class ASTVisitor;
};

class Literal : public Expression {
public:
    size_t value;

    int accept(ASTVisitor& visitor) {
        return visitor.visit(*this);
    }
};

class Addition : public Expression {
public:
    std::unique_ptr<Expression> left_term, right_term;

    int accept(ASTVisitor& visitor) override {
        return visitor.visit(*this);
    }
};

class Multiplication : public Expression {
public:
    std::unique_ptr<Expression> left_factor, right_factor;

    int accept(ASTVisitor& visitor) {
        return visitor.visit(*this);
    }
};

class ExpressionLexer {
public:
    ExpressionLexer() {};
    token_stream_t get_token_stream(std::string);
};

class Evaluator : public ASTVisitor {
private:
    int tab_no = 0;
public:
    int visit(Literal& node) override {
        std::cout << std::string(tab_no, '\t') << node.value << "\n";
        return node.value;
    }

    int visit(Addition& node) override {
        std::cout << std::string(tab_no, '\t') << "+" << "\n";
        tab_no++;

        return node.left_term->accept(*this) + node.right_term->accept(*this);
    }

    int visit(Multiplication& node) override {
        std::cout << std::string(tab_no, '\t') << "*" << "\n";
        tab_no++;

        return node.left_factor->accept(*this) * node.right_factor->accept(*this);
    }
};

token_stream_t ExpressionLexer::get_token_stream(std::string input) {
    token_stream_t tokens;
    std::string token;

    for (size_t i = 0; i < input.size(); ++i) {
        char ch = input[i];

        if (isspace(ch)) {
            continue;
        }

        if (ch == '(' || ch == ')') {
            tokens.push_back(std::string(1, ch));
        } else if (ch == '+' || ch == '*') {
            tokens.push_back(std::string(1, ch));
        } else if (isdigit(ch)) {
            token.clear();
            while (i < input.size() && isdigit(input[i])) {
                token += input[i];
                ++i;
            }
            --i;
            tokens.push_back(token);
        } else {
            throw std::runtime_error("Lexer error: unexpected character.");
        }
    }

    return tokens;
}

class ExpressionParser {
public:
    ExpressionParser() {};
    std::unique_ptr<Expression> parse(token_stream_t);
};

std::unique_ptr<Expression> ExpressionParser::parse(token_stream_t token_stream) {
    /**
     * Expression -> (+ Expression Expression) | (* Expression Expression) | number
     */

    std::function<bool(const std::string &)> is_number = [] (const std::string& str) {
        bool is_number = true;

        std::for_each(str.begin(), str.end(), [&is_number] (char c) {
            is_number = is_number && std::isdigit(c);
        });

        return is_number;
    };

    std::function<bool(const std::string&)> is_open_parenthesis = [] (const std::string& str) {
        return str == "(";
    };

    std::function<bool(const std::string&)> is_closed_parenthesis = [] (const std::string& str) {
        return str == ")";
    };

    std::function<bool(const std::string&)> is_addition = [] (const std::string& str) {
        return str == "+";
    };

    std::function<bool(const std::string&)> is_multiplication = [] (const std::string& str) {
        return str == "*";
    };

    std::function<void(bool)> check_parsing = [] (bool cond) {
        if (cond) {
            throw std::runtime_error("Error while trying to parse expression.");
        };
    };

    std::function<std::unique_ptr<Expression>(token_stream_t::iterator&)> parse_tree = [&] (auto& it) -> std::unique_ptr<Expression> {
        check_parsing(it == token_stream.end());

        if (is_number(*it)) {
            std::unique_ptr<Literal> expr = std::make_unique<Literal>();
            expr->value = std::stoi(*it);

            it++;

            return expr;
        }

        check_parsing(!is_open_parenthesis(*it));

        it++;
        check_parsing(it == token_stream.end());

        if (is_addition(*it)) {
            std::unique_ptr<Addition> expr = std::make_unique<Addition>();

            it++;
            expr->left_term = parse_tree(it);
            expr->right_term = parse_tree(it);

            check_parsing(it == token_stream.end());
            check_parsing(!is_closed_parenthesis(*it));

            return expr;
        }

        if (is_multiplication(*it)) {
            auto expr = std::make_unique<Multiplication>();

            it++;
            expr->left_factor = parse_tree(it);
            expr->right_factor = parse_tree(it);

            check_parsing(it == token_stream.end());
            check_parsing(!is_closed_parenthesis(*it));

            return expr;
        }

        throw std::runtime_error("Error while trying to parse expression.");
    };

    auto it = token_stream.begin();
    auto expr = parse_tree(it);

    check_parsing(it != token_stream.end());

    return expr;
}

void visit_and_print(std::unique_ptr<Expression> expr, std::unique_ptr<ASTVisitor> visitor) {
    int val = expr->accept(*visitor);
    std::cout << "\n" << val << "\n";
}

int main(void) {
    std::string expression;
    std::getline(std::cin, expression);

    std::unique_ptr<ExpressionLexer> lexer = std::make_unique<ExpressionLexer>();
    std::unique_ptr<ExpressionParser> parser = std::make_unique<ExpressionParser>();
    std::unique_ptr<Evaluator> evaluator = std::make_unique<Evaluator>();

    try {
        token_stream_t token_stream = lexer->get_token_stream(expression);
        std::unique_ptr<Expression> expr = parser->parse(token_stream);

        visit_and_print(std::move(expr), std::move(evaluator));
    } catch(const std::runtime_error& err) {
        std::cerr << err.what() << "\n";
        return 0;
    }

    return 0;
}

