#include <iostream>

using namespace std;

void transpose(int &n, int &m, int mat[101][101])
{
    int aux_mat[101][101];
    // realizeaza transpunerea intr-o matrice auxiliara
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            aux_mat[j][i] = mat[i][j];
    // inverseaza numarul de linii cu numarul de coloane dupa transpunere
    int aux = n;
    n = m;
    m = aux;
    // copiaza matricea auxiliara in matricea originala
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            mat[i][j] = aux_mat[i][j];
}

int main()
{
    int n, m;
    int mat[101][101];
    cin >> n >> m;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            cin >> mat[i][j];
    transpose(n, m, mat);
    for (int i = 1; i <= n; i++)
    {
        for (int j = 1; j <= m; j++)
            cout << mat[i][j] << ' ';
        cout << '\n';
    }
    return 0;
}

