void get_direction(char directie, int &movex, int &movey)
{
    switch (directie)
    {
    case 'N':
        movex = -1;
        movey = 0;
        break;
    case 'S':
        movex = 1;
        movey = 0;
        break;
    case 'E':
        movex = 0;
        movey = 1;
        break;
    case 'W':
        movex = 0;
        movey = -1;
        break;
    }
}

int s;
int main()
{
    int drum[505][505];

    cin >> n >> m;
    cin >> k;
    cin >> s;
    for (int i = 1; i <= n; i++)
    {
        mat[i][0] = -1;
        mat[i][m + 1] = -1;
    }
    for (int i = 1; i <= m; i++)
    {
        mat[0][i] = -1;
        mat[n + 1][i] = -1;
    }
    int posx, posy;
    char directie;
    for (int i = 1; i <= k; i++)
    {
        cin >> posx >> posy >> directie;
        mat[posx][posy] = int(directie);
    }
    int startx, starty;
    char start_directie;
    for (int i = 1; i <= s; i++)
    {
        cin >> startx >> starty >> start_directie;
        int start_movex = 0;
        int start_movey = 0;
        int movex = 0;
        int movey = 0;
        get_direction(start_directie, movex, movey);
        start_movex = movex;
        start_movey = movey;
        int l = 1;
        int x;
        int y;
        for (x = startx, y = starty; drum[x][y] == 0 || mat[x][y] == 0; x += movex, y += movey)
        {
            drum[x][y] = l;
            if (x == startx && y == starty && start_movex == movex && start_movey == movey && l > 1)
            {
                break;
            }
            if (mat[x][y] != 0)
            {
                if (mat[x][y] == -1) break;
                get_direction(char(mat[x][y]), movex, movey);
            }
            l++;
        }
        if(mat[x][y] == -1)
        {
            cout << drum[x-movex][y-movey] << " " << 0 << "\n";
        }
        else if (x == startx && y == starty && start_movex == movex && start_movey == movey)
        {
            cout << 0 << " "<< l-1 << "\n";
        }
        else
        {
            cout << drum[x][y]-1 << " " << drum[x-movex][y-movey]-drum[x][y]+1 << "\n";
        }

        for (int q = 1; q <= n; q++)
        {
            for (int o = 1; o <= m; o++)
            {
                drum[q][o] = 0;
            }
        }
    }

    return 0;
}

