    {0, -1, 0},
    {-1, 5, -1},
    {0, -1, 0}
};

matrix_t read_matrix(void)
{
    matrix_t matrix;

    size_t cols, rows, max_size;
    cin >> rows >> cols >> max_size;

    matrix.elems = vector<vector<int>> (rows, vector<int>(cols, 0));

    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++)
            cin >> matrix.elems[i][j];

    matrix.max_size = max_size;

    return matrix;
}

void apply_kernel(matrix_t &matrix)
{
    int rows = matrix.elems.size(), cols = matrix.elems[0].size();

    vector<vector<int>> new_matrix(rows, vector<int>(cols, 0));

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            int sum = 0;

            for (int di = -1; di <= 1; ++di) {
                for (int dj = -1; dj <= 1; ++dj) {
                    int row_index = i + di, col_index = j + dj;
                    int value;

                    if (row_index < 0 || row_index >= rows || col_index < 0 || col_index >= cols)
                        value = 0;
                    else
                        value = matrix.elems[row_index][col_index];

                    sum += kernel[1 + di][1 + dj] * value;
                }
            }

            if (sum < 0)
                sum = 0;
            else if (sum >= matrix.max_size)
                sum = matrix.max_size;

            new_matrix[i][j] = sum;
        }
    }

    matrix.elems = new_matrix;
}

