#include <tuple>

using namespace std;

pair<int, int> search_interval(const vector<long long> &v, long long x) {
    int left = 0;
    int right = v.size() - 1;

    while (left < right) {
        int mid = (left + right) / 2;
        if (v[mid] < x) {
            left = mid + 1;
        } else if (v[mid] > x) {
            right = mid - 1;
        } else {
            right = mid;
        }
    }

    if (v[right] != x) {
        return {0, -1};
    }
    int left_answer = right;

    left = 0;
    right = v.size() - 1;

    while (left < right) {
        int mid = (left + right + 1) / 2;
        if (v[mid] < x) {
            left = mid + 1;
        } else if (v[mid] > x) {
            right = mid - 1;
        } else {
            left = mid;
        }
    }

    int right_answer = right;

    return {left_answer, right_answer};
}

int main() {
    int n;
    long long x;

    cin >> n;
    vector<long long> v(n);
    for (int i = 0; i < n; i++) {
        cin >> v[i];
    }
    cin >> x;

    int left, right;
    std::tie(left, right) = search_interval(v, x);

    cout << (right - left) + 1 << '\n';

    return 0;
}

