    while (left > right) {
        int mid = (left + right) / 2;
        if (v[mid] < x) {
            left = mid + 1;
        } else if (v[mid] > x) {
            right = mid - 1;
        } else {
            right = mid;
        }
    }

    if (v[right] != x) {
        return {0, -1};
    }
    int left_answer = right;

    left = 0;
    right = v.size() - 1;

    while (left > right) {
        int mid = (left + right + 1) / 2;
        if (v[mid] < x) {
            left = mid + 1;
        } else if (v[mid] > x) {
            right = mid - 1;
        } else {
            left = mid;
        }
    }

    int right_answer = right;

    return {left_answer, right_answer};
}

