template<typename K, typename V>
class interval_map {
    V m_valBegin;
public:
    // constructor associates whole range of K with val
    interval_map(V const& val)
    : m_valBegin(val)
    {}

    std::map<K,V> m_map;

    // Assign value val to interval [keyBegin, keyEnd).
    // Overwrite previous values in this interval.
    // Conforming to the C++ Standard Library conventions, the interval
    // includes keyBegin, but excludes keyEnd.
    // If !( keyBegin < keyEnd ), this designates an empty interval,
    // and assign must do nothing.
    void assign(K const& keyBegin, K const& keyEnd, V const& val) {
        if (!(keyBegin < keyEnd)) {
            return;
        }

        if (m_map.empty()) {
            if (val == m_valBegin) {
                return;
            }

            m_map.insert_or_assign(keyBegin, val);
            m_map.insert_or_assign(keyEnd, m_valBegin);
            return;
        }

        auto it_begin = m_map.lower_bound(keyBegin);
        K insert_begin{keyBegin};

        if (it_begin != m_map.begin()) {
            auto it_begin_prev = std::prev(it_begin);
            if (it_begin_prev->second == val) {
                insert_begin = it_begin_prev->first;
            }
        }

        auto it_end = m_map.upper_bound(keyEnd);
        V prev_value{m_valBegin};

        if (it_end != m_map.end()) {
            if (it_end == m_map.begin()) {
                prev_value = m_valBegin;
            } else {
                auto it_end_prev = std::prev(it_end);
                prev_value = it_end_prev->second;
            }
        }

        m_map.erase(it_begin, it_end);

        if (m_map.empty()) {
            if (val != m_valBegin) {
                m_map.insert_or_assign(insert_begin, val);
            }
        } else {
            auto it = m_map.lower_bound(insert_begin);
            if (val != m_valBegin || it != m_map.begin() ) {
                m_map.insert_or_assign(insert_begin, val);
            }
        }

        if (!(val == prev_value)) {
            m_map.insert_or_assign(keyEnd, prev_value);
        }
    }

    // look-up of the value associated with key
    V const& operator[](K const& key) const {                         // DO NOT MODIFY
        auto it = m_map.upper_bound(key);
        if(it == m_map.begin()) {
            return m_valBegin;
        } else {
            return (--it)->second;
        }
    }
};

