#define ERR -1
#define OK 1

typedef unsigned int uint;

struct client_state;

// Used by the manager to allocate the dynamic context
client_state* new_state();

// The current client sends x to the next client, the manager decides whether or
// not to add x to that client's register
// Returns: ERR or OK
int send(uint x);

// Client i writes x to stdout
void write(uint x);

// Return the current client's register
uint get_register();

// Sets the value of the current client's register
// Returns: ERR or OK
int set_register(unsigned int x);

/////////////// These functions need to be defined in client.cpp ///////////////

// Called by the manager for the transmitter to begin sending its message.
void begin_message(client_state *state, uint msg);

// Called by the manager at each cycle, for each client in ascending order.
void update(client_state *state);

////////////////////////////////////////////////////////////////////////////////

// ---- client.cpp: scrie funcția step3() ----
#define SEND_BITS_STEPS 60

using namespace std;

struct client_state {
    uint cycle = 0;

    uint msg = 0;
    bool is_last = false;
    bool is_first = false;

    uint pow = 1;
    uint final_value = 0;
};

// Managerul are nevoie de asta si e obligatoriu
client_state* new_state() {
    return new client_state;
}

////////////////////////////// API IMPLEMENTATION //////////////////////////////

void begin_message(client_state *state, uint msg) {
    state->msg = msg;
    state->is_last = true;
}

// Toti clientii trimit 1, in primul ciclu
void step1() {
    send(1);
}

// Clientii verifica sa vada daca au valoarea 0 in registru.
// Daca are registrul 1, inseamna ca in primul ciclu, un client din stanga
//  sa i-a trimis un numar. Deci, el nu poate fi primul client.
void step2(client_state *state) {
    if (get_register() == 0) {
        state->is_first = true;
    }
    set_register(0);
}

// Am gasit o metoda. Pot trimite mesajul in binar. Se va propaga de la ultimul
//  client pana la primul.
// Ideea este in codul de eroare care e returnat de send.
// Se poate transmite 0 sau 1, in functie de ceea ce returneaza send: OK sau ERR
// Ultimul client isi seteaza registrul 499 sau 500.
