class complex
{
private:
    int r, i;   // r - partea reala, i - partea imaginara
public:
    complex();  // creeaza numarul imaginar nul
    complex(int pr, int pi); // pr - valoarea termenului real, pi - val. term. imaginar
    string afisare(); // pregateste un sir pentru a fi afisat
    int real();     // returneaza partea reala
    int imaginar(); // returneaza partea imaginara
    void set(int pr, int pi); // stabileste valoarea partii reale si a celei imaginare
};
// aici va fi scris codul tau
complex::complex() : r(0), i(0) {}
complex::complex(int pr, int pi) : r(pr), i(pi) {}
int complex::real() { return r; }
int complex::imaginar() { return i; }
void complex::set(int pr, int pi) { r = pr; i = pi; }
string complex::afisare()
{
    if (i == 0) return to_string(r);
    string im = (i == 1 ? "" : i == -1 ? "-" : to_string(i)) + "i";
    if (r == 0) return im;
    return to_string(r) + (i > 0 ? "+" : "") + im;
}
complex operator+(complex a, complex b) { return complex(a.real() + b.real(), a.imaginar() + b.imaginar()); }
complex operator-(complex a, complex b) { return complex(a.real() - b.real(), a.imaginar() - b.imaginar()); }
complex operator*(complex a, complex b)
{
    return complex(a.real() * b.real() - a.imaginar() * b.imaginar(), a.real() * b.imaginar() + a.imaginar() * b.real());
}

