    int n, root;

    cin >> n;

    // 0 is also a perfect square, so we need to check it
    while (n >= 0) {
        // take the integer part of the square root of n
        root = sqrt(n); 

        // if n is a perfect square, print it
        if (n == root * root) {
            cout << n << " ";
        }

        n--;
    }

    return 0;
}

