#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define N 100
#define MAXLEN 50

#define MIN_GRADE 1
#define MAX_GRADE 10

struct {
    int values[N];
    int next_index;
} grades;

struct {
    int grade_distribution[MAX_GRADE-MIN_GRADE+2];
    double average;
    double mean_squared_error;
} stats;

void read_input()
{
    FILE *fin = stdin;
    if(fin == NULL) {
        fprintf(stderr, "Failed to open input file.\n");
        exit(-1);
    }

    char first_name[MAXLEN], last_name[MAXLEN], email[MAXLEN], phone[MAXLEN], grade[MAXLEN];
    int grade_value;

    fscanf(fin, "%*[^\n]\n"); // or just copy/paste the fscanf below

    while(fscanf(fin, "%s%s%s%s%s", first_name, last_name, email, phone, grade) != EOF)
    {
        grade_value = atoi(grade);
        grades.values[grades.next_index++] = grade_value;
    }
}

void compute_average()
{
    int sum = 0, i;

    for(i = 0; i < grades.next_index; i++)
        sum += grades.values[i];
    stats.average = (double)sum / grades.next_index;
}

void compute_mean_squared_error()
{
    int i;
    double dif = 0, sum = 0;

    for(i = 0; i < grades.next_index; i++)
    {
        dif = stats.average - grades.values[i];
        sum += dif * dif;
    }
    stats.mean_squared_error = sqrt((double)sum / (grades.next_index-1));

}

void compute_grade_distribution()
{
    int i;

    for(i = 0; i < grades.next_index; i++)
        stats.grade_distribution[grades.values[i]]++;
}

void compute_statistics()
{
    compute_average();
    compute_mean_squared_error();
    compute_grade_distribution();
}

void write_output()
{
    int i;
    FILE *fout = stdout;
    if(fout == NULL) {
        fprintf(stderr, "Failed to open output file.\n");
        exit(-1);
    }

    fprintf(fout, "%lf %lf\n", stats.average, stats.mean_squared_error);
    for(i = MIN_GRADE; i <= MAX_GRADE; i++)
        fprintf(fout, "%d ", stats.grade_distribution[i]);
}

int main()
{
    int ret = 0;

    read_input();
    compute_statistics();
    write_output();

    return ret;
}

