    for (map<string, Person*>::iterator it = m_students.begin(); it != m_students.end(); ++it)
    {
        if (first)
        {
            cout << ' ' << it->first;
            first = false;
        }
        else
            cout << ", " << it->first;
    }
    cout << ".\n";
}

