#include <vector>

using namespace std;

void print_spiral(int m, int n, vector<vector<int> >&matrix)
{
  int i;
  int x = 0, y = 0;

  while (m > 0 && n > 0) {
    if (m == 1) {
      for (i = 0; i < n; i++) {
        printf("%d ",matrix[x][y++]);
      }
      break;
    }
    else if (n == 1){
      for (i = 0; i < m; i++){
        printf("%d ", matrix[x++][y]);
      }
      break;
    }

    //go right
    for (i = 0; i < n; i++) {
      printf("%d ", matrix[x][y++]);
    }

    //go down
    for (i = 0; i < m; i++) {
      printf("%d ", matrix[x--][y]);
    }

    //go left
    for (i = 0; i < n; i++) {
      printf("%d ", matrix[x][y--]);
    }

    //go up
    for (i = 0; i < m; i++) {
      printf("%d ", matrix[x++][y]);
    }

    x++;
    y++;
    m--;
    n--;
  }
